\sum_{i=1}^{t} (i-1)^m(i)^m - \sum_{i=1}^{t-2} (i-1)^m(i)^m & =   (t-2)^m(t-1)^m + (t-1)^m(t)^m\\
& = (t-1)^m ((t-1 + 1)^m + (t-1 -1 )^m ) \\
&= (t-1)^m (\sum_{l=0}^m {m\choose l} (t-1)^{m-l} (1^l + (-1)^l))\\
& = (t-1)^m\sum_{\substack{l \in {0,\ldots ,m} \\\text{ and even} }} 2 {m\choose l} (t-1)^{m-l}\\
 & = \sum_{j = 0}^{\lfloor \frac{m}{2} \rfloor} 2 {m \choose 2j} (t-1)^{2m-2j}.
 \end{split} \end{equation*}
